/*
 * iOS 静音键兼容：让 iPhone 在静音（铃声关闭）状态下也能听到网页声音。
 * 原理：
 * 1. Safari 16.4+ 提供 navigator.audioSession，把类型设为 "playback"（和音乐/视频 App 一样，不受静音键影响）。
 * 2. 旧版 iOS：在用户第一次点击时播放一段循环的无声 <audio>，把整个页面的音频会话切换成 "playback"，
 *    之后 Web Audio（AudioContext）发出的声音也不再被静音键屏蔽。
 * 3. 记录页面创建的所有 AudioContext，在用户点击时自动 resume，避免 iOS 上音频一直处于挂起状态。
 * 必须在游戏其它脚本之前加载。
 */
(function () {
  "use strict";
  try {
    if (navigator.audioSession) navigator.audioSession.type = "playback";
  } catch (e) {}

  var contexts = [];
  ["AudioContext", "webkitAudioContext"].forEach(function (name) {
    var Native = window[name];
    if (!Native || Native.__iosPatched) return;
    var Patched = function () {
      var ctx = new (Function.prototype.bind.apply(Native, [null].concat([].slice.call(arguments))))();
      contexts.push(ctx);
      return ctx;
    };
    Patched.prototype = Native.prototype;
    Patched.__iosPatched = true;
    try { window[name] = Patched; } catch (e) {}
  });

  var isIOS = /iP(hone|ad|od)/.test(navigator.userAgent) ||
    (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
  var silent = null;

  function unlock() {
    if (isIOS && !navigator.audioSession && !silent) {
      silent = document.createElement("audio");
      silent.setAttribute("x-webkit-airplay", "deny");
      silent.preload = "auto";
      silent.loop = true;
      silent.src = "data:audio/mpeg;base64,";
      silent.play().catch(function () {});
    }
    contexts.forEach(function (ctx) {
      if (ctx.state === "suspended" && ctx.resume) ctx.resume().catch(function () {});
    });
  }

  ["touchend", "click", "keydown"].forEach(function (ev) {
    document.addEventListener(ev, unlock, { capture: true, passive: true });
  });
  document.addEventListener("visibilitychange", function () {
    if (!document.hidden) unlock();
  });
})();
